script:
(function () {
  'use strict';
  // Discount maths.
  //   Sale price: after first discount = price x (1 - d%) or price - $d; extra % off applies to the
  //     already reduced price; a $ coupon comes off next (not below $0); sales tax is charged on the
  //     price after all discounts; shipping is added last and is not taxed.
  //   Original price = sale price / (1 - d%).   Percent off = (original - sale) / original.
  // Verified (Node scratch test): $59.99 at 15% off -> $50.99, you save $9.00; $100 with 20% then an
  // extra 10% off -> $72.00 (28% total, not 30%); $100, 20% off, $10 coupon, 8% tax, $5 shipping
  // -> $70.00 + $5.60 tax + $5.00 = $80.60; $85 sale at 15% off -> original $100.00; $80 -> $60
  // is 25% off. Over-sized discounts, 100% "original price" and negative inputs show an error.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 0, maximumFractionDigits: 2 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function salePrice(o) {
    var first = o.type === 'percent' ? o.price * (1 - o.disc / 100) : o.price - o.disc;
    var extra = first * (1 - o.extra / 100);
    var afterCoupon = Math.max(0, extra - o.coupon);
    var tax = afterCoupon * o.tax / 100;
    return { first: first, extra: extra, net: afterCoupon, tax: tax, total: afterCoupon + tax + o.ship,
             saved: o.price - afterCoupon, rate: o.price > 0 ? (o.price - afterCoupon) / o.price : 0 };
  }

  function originalPrice(sale, d) { return sale / (1 - d / 100); }
  function percentOff(orig, sale) { return orig > 0 ? (orig - sale) / orig : 0; }

  function set(id, text) { document.getElementById(id).textContent = text; }
  function show(id, on) { document.getElementById(id).hidden = !on; }

  function update() {
    var mode = document.getElementById('dcMode').value;
    var type = document.getElementById('dcType').value;
    show('dcSaleInputs', mode === 'sale');
    show('dcOriginalInputs', mode === 'original');
    show('dcPercentInputs', mode === 'percent');
    show('dcBreakdown', mode === 'sale');
    set('dcDiscAffixPre', type === 'amount' ? '$' : '');
    set('dcDiscAffixPost', type === 'percent' ? '%' : '');
    show('dcDiscAffixPre', type === 'amount');
    show('dcDiscAffixPost', type === 'percent');
    var error = document.getElementById('dcError');
    var msg = '';

    if (mode === 'sale') {
      var o = { price: num('dcPrice'), type: type, disc: num('dcDisc'), extra: num('dcExtra'),
                coupon: num('dcCoupon'), tax: num('dcTax'), ship: num('dcShip') };
      if ([o.price, o.disc, o.extra, o.coupon, o.tax, o.ship].some(isNaN) || o.price < 0 || o.disc < 0 ||
          o.extra < 0 || o.extra > 100 || o.coupon < 0 || o.tax < 0 || o.tax > 30 || o.ship < 0) {
        msg = 'Enter non-negative amounts, an extra discount up to 100% and a sales tax rate up to 30%.';
      } else if (type === 'percent' && o.disc > 100) {
        msg = 'A percentage discount can\'t be more than 100%.';
      } else if (type === 'amount' && o.disc > o.price) {
        msg = 'The amount off can\'t be more than the original price.';
      }
      if (!msg) {
        var r = salePrice(o);
        set('dcMainLabel', 'Total to pay');
        set('dcMain', money.format(r.total));
        set('dcSecondLabel', 'Price after discounts');
        set('dcSecond', money.format(r.net));
        set('dcSaved', money.format(r.saved));
        set('dcFourthLabel', 'Total discount');
        set('dcRate', pct.format(r.rate));
        set('dcRowPrice', money.format(o.price));
        set('dcRowFirst', money.format(r.first));
        set('dcRowExtra', money.format(r.extra));
        set('dcRowCoupon', money.format(r.net));
        set('dcRowTax', money.format(r.tax));
        set('dcRowShip', money.format(o.ship));
        set('dcRowTotal', money.format(r.total));
        show('dcExtraRow', o.extra > 0);
        show('dcCouponRow', o.coupon > 0);
        show('dcShipRow', o.ship > 0);
        var dropped = o.coupon > 0 && r.extra - o.coupon < 0;
        show('dcCouponNote', dropped);
      }
    } else if (mode === 'original') {
      var sale = num('dcSaleKnown'), d = num('dcPctKnown');
      if (isNaN(sale) || isNaN(d) || sale < 0 || d < 0 || d >= 100) {
        msg = 'Enter a sale price of $0 or more and a discount from 0% up to (but not including) 100%.';
      } else {
        var orig = originalPrice(sale, d);
        set('dcMainLabel', 'Original price');
        set('dcMain', money.format(orig));
        set('dcSecondLabel', 'Sale price');
        set('dcSecond', money.format(sale));
        set('dcSaved', money.format(orig - sale));
        set('dcFourthLabel', 'Discount');
        set('dcRate', pct.format(d / 100));
      }
    } else {
      var origK = num('dcOrigKnown'), saleK = num('dcSaleKnown2');
      if (isNaN(origK) || isNaN(saleK) || origK <= 0 || saleK < 0) {
        msg = 'Enter an original price above $0 and a sale price of $0 or more.';
      } else if (saleK > origK) {
        msg = 'The sale price is higher than the original price, so there is no discount.';
      } else {
        set('dcMainLabel', 'Discount');
        set('dcMain', pct.format(percentOff(origK, saleK)));
        set('dcSecondLabel', 'Original price');
        set('dcSecond', money.format(origK));
        set('dcSaved', money.format(origK - saleK));
        set('dcFourthLabel', 'Sale price');
        set('dcRate', money.format(saleK));
      }
    }
    error.hidden = !msg;
    error.textContent = msg;
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('dcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
